@Test
    public void testAdjustStoragePathIfNecessaryUseAdjusterResponse() {
        final String response = "Hello";
        Assert.assertEquals(
            response,
            PublishHelperUtils.adjustStoragePathIfNecessary(
                "blah",
                (String path) -> { return response; }
            )
        );
    }

